z['收盘差']=(z.分钟末收-z.日收).abs();z['最高差']=(z.分钟最高-z.日高).abs();z['最低差']=(z.分钟最低-z.日低).abs();z['总量比']=z.分钟总量/z.日量.replace(0,np.nan);coverage=z.groupby('d0_date').agg(候选=('symbol','size'),可用=('分时有效','sum'),收盘差超1分=('收盘差',lambda s:int(s.gt(.011).sum())),最高差超1分=('最高差',lambda s:int(s.gt(.011).sum())),最低差超1分=('最低差',lambda s:int(s.gt(.011).sum()),)).reset_index();coverage.to_csv(P/'公开分时逐日审计.csv',index=False);z[['stk_code','d0_date','分钟记录数','分时有效','收盘差','最高差','最低差','总量比']].to_csv(P/'公开分时逐股审计.csv',index=False);print(coverage.to_string(index=False));print('量比',z.loc[z.分时有效,'总量比'].describe().to_string())
